import { UnitSpec } from './UnitSpec';
export class PacketScaler {
  scaleNativePacket(value: number, spec: UnitSpec): number {
    return Math.round(value * spec.factor);
  }
}

sources.GateRules.ts:
export class GateRules {
  allowScheme(uri: string): boolean {
    const scheme = uri.split(':')[0].toLowerCase();
    return scheme === 'https';
  }
}

